<template>
  <main class="model-billing">
    <header class="hero">
      <div><span class="eyebrow">ADMIN CONSOLE / MODEL BILLING</span><h1>模型与计费管理</h1><p>统一查看已接入模型，并集中维护每个模型的积分扣除规则。</p></div>
      <t-button variant="outline" @click="loadModels" :loading="loading">刷新模型</t-button>
    </header>
    <div class="summary"><div><b>{{ modelCount }}</b><span>已接入模型</span></div><div><b>{{ vendorCount }}</b><span>供应商</span></div><div><b>{{ enabledCount }}</b><span>可用模型</span></div></div>
    <nav class="tabs"><button :class="{active: tab==='models'}" @click="tab='models'">模型目录</button><button :class="{active: tab==='pricing'}" @click="tab='pricing'">积分计费规则</button></nav>
    <section v-if="tab==='models'" class="panel"><div class="panel-head"><div><h2>模型目录</h2><span>模型接入在「供应商设置」完成，价格在计费规则中维护</span></div><div class="head-actions"><t-input v-model="search" placeholder="搜索模型" clearable style="width:180px"/><t-select v-model="vendorFilter" clearable placeholder="全部供应商" style="width:180px"><t-option v-for="v in vendorNames" :key="v" :value="v" :label="v"/></t-select><t-button variant="outline" @click="tab='pricing'">管理价格</t-button></div></div><t-empty v-if="!loading&&!filteredModels.length" description="暂无匹配模型"/><div v-else class="grid"><article v-for="m in filteredModels" :key="m.key"><div class="model-top"><strong>{{ m.name }}</strong><t-switch :value="m.enabled" size="small" @change="toggleVendor(m)"/></div><small>{{ m.vendor }} · {{ m.key }}</small><div class="tags"><span v-for="tag in m.tags" :key="tag">{{ tag }}</span></div><div class="model-meta"><label :class="m.enabled?'ok':''">{{ m.enabled?'可用':'已停用' }}</label><span v-if="m.default">默认模型</span></div></article></div></section>
    <section v-else class="panel pricing"><PricingView /></section>
  </main>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import axios from '@/utils/axios';
import PricingView from './PricingView.vue';
const tab=ref<'models'|'pricing'>('models'); const loading=ref(false); const models=ref<any[]>([]); const overrides=ref<any[]>([]); const vendorFilter=ref(''); const search=ref('');
const vendorNames=computed(()=>[...new Set(models.value.map(m=>m.vendor))]); const filteredModels=computed(()=>models.value.filter(m=>(!vendorFilter.value||m.vendor===vendorFilter.value)&&(!search.value||m.name.toLowerCase().includes(search.value.toLowerCase()))));
const modelCount=computed(()=>models.value.length); const vendorCount=computed(()=>new Set(models.value.map(m=>m.vendor)).size); const enabledCount=computed(()=>models.value.filter(m=>m.enabled).length);
async function loadModels(){ loading.value=true; try { const [vr,or]=await Promise.all([axios.post('/setting/vendorConfig/getVendorList'),axios.get('/setting/pointsConfig/overrides')]); overrides.value=or.data||[]; models.value=(vr.data||[]).flatMap((v:any)=>(v.models||[]).map((m:any,i:number)=>{const name=typeof m==='string'?m:(m.name||m.modelName||m.id); const type=typeof m==='object'?m.type:''; const hit=overrides.value.find(o=>String(o.vendor_id)===String(v.id)&&o.model_name===name); return {key:typeof m==='string'?m:(m.modelName||m.id||m.name),name,vendor:v.name||v.id,vendorId:v.id,enabled:v.enable===1||v.enable===true,default:i===0,rate:Number(hit?.multiplier??1),tags:type?([type==='text'?'文本':type==='image'?'图片':'视频']):['通用模型']};})); } catch(e:any){ window.$message?.error?.(e.message||'模型列表加载失败'); } finally { loading.value=false; } }
async function toggleVendor(model:any){ const next=model.enabled?0:1; try { await axios.post('/setting/vendorConfig/enableVendor',{id:model.vendorId,enable:next}); models.value.filter(m=>m.vendorId===model.vendorId).forEach(m=>m.enabled=!!next); window.$message?.success?.(next?'供应商已启用':'供应商已停用'); } catch(e:any){ window.$message?.error?.(e.message||'状态更新失败'); } }
onMounted(loadModels);
</script>
<style scoped>
.model-billing{padding:30px clamp(18px,3vw,42px);color:#172033}.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:24px}.eyebrow{font-size:11px;color:#f2762e;font-weight:700;letter-spacing:.14em}.hero h1{margin:8px 0 0;font-size:30px}.hero p{margin:8px 0 0;color:#7d8491;font-size:13px}.summary{display:flex;gap:12px;margin-bottom:22px}.summary div{min-width:150px;padding:16px 20px;background:#fff;border:1px solid #eee;border-radius:14px}.summary b{display:block;font-size:25px}.summary span{font-size:12px;color:#8b93a1}.tabs{display:flex;gap:8px;margin-bottom:14px}.tabs button{border:0;background:#f1f3f7;padding:10px 20px;border-radius:9px;color:#697386;cursor:pointer}.tabs button.active{background:#f2762e;color:#fff}.panel{background:#fff;border:1px solid #eee;border-radius:16px;padding:22px}.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.panel-head h2{margin:0;font-size:18px}.panel-head span{font-size:12px;color:#9299a6}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}.grid article{padding:16px;border:1px solid #edf0f4;border-radius:12px}.model-top{display:flex;justify-content:space-between;align-items:center}.model-top i{width:8px;height:8px;border-radius:50%;background:#cbd1da}.model-top i.on{background:#20b26b;box-shadow:0 0 0 4px #e5f8ee}.grid small{display:block;color:#8a92a0;margin:8px 0;font-size:12px}.grid label{font-size:11px;color:#20a56a}.pricing{padding:0}.pricing :deep(.pricingWrap){padding:24px}
@media(max-width:650px){.hero{align-items:flex-start;flex-direction:column}.summary{flex-wrap:wrap}.summary div{flex:1;min-width:120px}}
</style>
